struct PersonRow { id: i64, last_name: String, deps: i32 }

impl PersonRow {
    async fn find(pool: &PgPool, id: i64) -> sqlx::Result<Option<Self>> {
        sqlx::query_as::<_, Self>("SELECT id, last_name, deps FROM people WHERE id = $1")
            .bind(id).fetch_optional(pool).await
    }
    async fn update(&self, pool: &PgPool) -> sqlx::Result<()> {
        sqlx::query("UPDATE people SET deps = $2 WHERE id = $1").bind(self.id).bind(self.deps).execute(pool).await.map(|_| ())
    }
}

